-- ============================================================================
-- PARTIE 14 — Contenu du module 3 « Soins, sommeil, alimentation » (3 séquences)
-- Source : Projet pédagogique Koalakids (soins d'hygiène, repas, sommeil).
-- Les séquences RESTENT EN BROUILLON.
-- À exécuter en 7 temps : 14.1a, 14.1b, 14.2a, 14.2b, 14.3a, 14.3b, puis 14c.
-- Relançable : la trame est remplacée, les blocs ne sont ajoutés qu'une fois.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 14.1a Trame de la séquence 1/3 (Apport). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Un soin, un repas, une sieste : à chaque fois, l'enfant doit sentir que l'adulte s'occupe de lui.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire en quoi un soin, un repas ou une sieste est un moment de relation individuelle, et d'adapter son geste au rythme de l'enfant plutôt qu'à celui de l'organisation.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Besoins physiologiques de l'enfant (soins, alimentation, sommeil)"}, "duree_min": 45, "materiel": ["Paperboard", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Présenter les 3 séances du module : apport, analyse d'une situation vécue, test d'une pratique.", "Chacun pense à un soin, un repas ou une sieste de la semaine qui s'est particulièrement bien passé, sans le raconter."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Un soin, un repas, une sieste : à chaque fois, l'enfant doit sentir que l'adulte s'occupe de lui, pas seulement de son corps.", "idees": ["Les soins d'hygiène (couche, mains, toilettes) ne se font pas de façon systématique et groupée : on les envisage en accompagnement individuel. Prendre son temps est la devise, et une bonne technique assure aussi le bien-être de l'enfant.", "Au repas, c'est l'enfant qui donne le rythme. On est attentif à ce qu'il manifeste (faim, plaisir, dégoût, satiété), on ne le force pas à goûter, on n'exige pas qu'il finisse son assiette.", "Pour le sommeil, on couche l'enfant quand il montre des signes de fatigue, avec des rituels qui le sécurisent. Un enfant qui pleure dans son lit doit être rassuré, pas forcément levé."], "support": "Projet pédagogique Koalakids, « Comment accompagner les enfants aux soins d'hygiène, au repas, au sommeil ? »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir un soin, un repas ou une sieste vécu cette semaine. On analyse ce que fait l'adulte, pas ce qu'est l'enfant.", "questions": ["Que s'est-il passé ? (les faits, ce que l'enfant a fait ou dit)", "Quel besoin de l'enfant ? (manger, dormir, être changé, finir son jeu, être rassuré)", "Le geste était-il adapté à son rythme ?", "Que faire autrement ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : proposer à un enfant de finir son jeu avant d'aller changer sa couche.", "Exemple : m'installer à la hauteur de l'enfant et prendre mon temps pendant un repas.", "Exemple : observer les signes de fatigue d'un enfant et les noter."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Annoncer la séance 2/3 : analyse d'une situation vécue, avec un focus sur les signes de l'enfant (faim, fatigue, refus)."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 3 % 1/3 %';
-- FIN 14.1a

-- ---------------------------------------------------------------------------
-- 14.1b Blocs de la séquence 1/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Des gestes de tous les jours, des moments de relation", "paragraphes": ["Changer une couche, nourrir un enfant, l'accompagner à la sieste : ces gestes reviennent plusieurs fois par jour. Ils peuvent devenir **routiniers**, ou devenir **les moments privilégiés** de la relation avec chaque enfant.", "Cette première séance pose un repère : à chaque soin, à chaque repas, à chaque sieste, l'enfant doit ressentir que l'adulte s'occupe de **lui**."]}$kk$),
  (1,'citation',$kk${"texte": "Prendre son temps devient la devise de l'accompagnement aux soins d'hygiène."}$kk$),
  (2,'retenir',$kk${"titre": "À retenir", "points": ["**Un accompagnement individuel :** les soins ne se font pas de façon systématique et groupée.", "**Le rythme de l'enfant :** au repas, à la sieste, au change, on suit ses signes plutôt que l'horloge.", "**Ce que l'enfant vit compte :** on lui parle, on lui explique, on respecte son corps et son refus du moment."]}$kk$),
  (3,'reflexion',$kk${"question": "Quel moment de la journée vous paraît le plus routinier ? Qu'est-ce qui vous aiderait à le vivre comme un moment de relation ?", "sous_titre": "Il n'y a pas de bonne réponse : on cherche à comprendre ce qui rend ces moments faciles ou difficiles.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer cette semaine", "titre": "Trois gestes pour un moment de relation", "etapes": [{"titre": "Annoncer.", "texte": "Je dis à l'enfant ce que nous allons faire et pourquoi, avant de le toucher."}, {"titre": "Laisser un choix.", "texte": "Finir son jeu, choisir la couche, faire seul ou être aidé : un choix simple dans un cadre donné."}, {"titre": "Rester disponible.", "texte": "Je prends mon temps, je lui parle et j'écoute ce qu'il manifeste."}], "note": "Choisissez un seul de ces gestes et testez-le toute la semaine."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 3 % 1/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 14.1b

-- ---------------------------------------------------------------------------
-- 14.2a Trame de la séquence 2/3 (Analyse d'une situation vécue). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Avant d'agir, je regarde ce que l'enfant me dit : ses signes de fatigue, de faim, de refus.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de repérer les signes de l'enfant (faim, fatigue, refus) avant d'agir, et d'en tirer un geste adapté au soin, au repas ou à la sieste.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Besoins physiologiques de l'enfant (soins, alimentation, sommeil)"}, "duree_min": 45, "materiel": ["Paperboard (pour lister les signes de fatigue, de faim et de refus observés sur le site, sans nom)", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Retour sur la semaine : chacun dit en une phrase ce qu'il a essayé de son engagement « Cette semaine, je… », sans l'évaluer.", "Demander qui apporte la situation à analyser."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Avant d'agir, je regarde ce que l'enfant me dit : ses signes de fatigue, de faim, de refus.", "idees": ["Chaque enfant a ses propres signes de fatigue (bâillements, yeux qui se frottent, doudou réclamé, excitation, pâleur…). Prendre le temps de les observer permet de le coucher au bon moment, sans le maintenir au lit s'il n'a pas sommeil.", "Lors d'un soin, pour l'enfant, changer sa couche peut signifier passivité, attente, abandon de son jeu. Son refus peut venir de là. On repère le meilleur moment, on peut finir son jeu avant, et un autre adulte peut parfois faciliter le soin.", "À table, on accepte ce que l'enfant manifeste : un « non » entendu du premier coup, un refus momentané, un aliment recraché. On ne fait ni chantage affectif ni chantage avec les aliments."], "support": "Projet pédagogique Koalakids, « Comment accompagner les enfants aux soins d'hygiène, au repas, au sommeil ? »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir un refus, des pleurs ou une résistance vécus cette semaine pendant un soin, un repas ou une sieste. On cherche ce que l'enfant disait.", "questions": ["Que s'est-il passé ? (les faits)", "Quel signe l'enfant montrait-il ? (fatigue, faim, satiété, refus, besoin de finir son jeu)", "Qu'est-ce que l'adulte a fait ?", "Que faire autrement la prochaine fois ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : laisser l'enfant décider du rythme des cuillères.", "Exemple : attendre quelques instants, en restant près de lui, avant de relever un enfant qui pleure dans son lit.", "Exemple : expliquer à l'enfant ce que je vais faire avant un soin."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Annoncer la séance 3/3 : retour d'expérience sur la pratique testée, avec un focus sur l'autonomie et les choix de l'enfant."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 3 % 2/3 %';
-- FIN 14.2a

-- ---------------------------------------------------------------------------
-- 14.2b Blocs de la séquence 2/3. Attendu : 6 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Lire les signes avant d'agir", "paragraphes": ["Un enfant ne dit pas toujours « j'ai sommeil » ou « je n'ai plus faim ». Il le montre : un regard dans le vague, la tête qui se détourne, une main qui repousse.", "Le repérer demande du **temps d'observation**. C'est ce qui permet d'adapter le geste à l'enfant plutôt que l'enfant à l'organisation."]}$kk$),
  (1,'scenes',$kk${"titre": "Trois situations que vous reconnaîtrez", "items": [{"lettre": "A", "titre": "Elle refuse le change en plein jeu", "texte": "Zoé empile des cubes depuis dix minutes. On l'appelle pour changer sa couche : elle s'agrippe à l'étagère et pleure.", "analyse": "pour elle, le soin signifie abandonner son jeu et attendre. On peut lui laisser finir sa construction, lui dire ce qui va se passer, et lui laisser un choix (debout ou allongée, avec qui). Un refus n'est pas un caprice."}, {"lettre": "B", "titre": "Il serre les lèvres à la cuillère", "texte": "Adam détourne la tête. L'adulte insiste : « Encore une bouchée, une seule. »", "analyse": "c'est à l'enfant de donner le rythme. Il montre qu'il n'a plus faim ou qu'il veut autre chose. On accepte son refus du moment, sans chantage, et on lui laisse manipuler la cuillère ou la nourriture."}, {"lettre": "C", "titre": "Elle pleure dans son lit", "texte": "Léna pleure depuis cinq minutes après avoir été couchée. Un collègue veut la relever.", "analyse": "elle est peut-être en train de s'endormir. On reste près d'elle, on la rassure, on attend un peu avant de la lever. Un enfant qui pleure dans son sommeil doit être rassuré, pas forcément levé. Si elle n'a vraiment pas sommeil, on la laisse aller jouer et on la recouchera plus tard."}]}$kk$),
  (2,'comparaison',$kk${"intro": "Pour accompagner un soin, un repas ou une sieste.", "plutot": ["Adapter le moment et le rythme à l'enfant.", "Lui parler et lui expliquer ce qui se passe pour lui.", "Lui laisser des choix dans un cadre donné.", "Accepter son refus du moment, sans le forcer ni le culpabiliser."], "eviter": ["Faire le soin ou le repas de façon systématique et groupée.", "Exiger qu'il finisse son assiette ou qu'il goûte.", "Faire du chantage affectif ou avec les aliments.", "Maintenir au lit un enfant qui n'a pas sommeil."]}$kk$),
  (3,'texte',$kk${"titre": "Un rappel de sécurité à relire avec le protocole", "paragraphes": ["Pour le couchage, le projet pédagogique rappelle : bébés qui ne se déplacent pas couchés sur le dos, sans oreiller, couette ni objet qui pourrait leur recouvrir le visage ; lits éloignés des sources de chaleur ; température de la chambre qui n'excède pas 20 degrés ; surveillance de la sieste toutes les 15 minutes.", "Ces consignes ne se discutent pas : elles se relisent régulièrement en équipe, avec votre protocole."]}$kk$),
  (4,'reflexion',$kk${"question": "Quels signes montrent qu'un enfant que vous connaissez bien a sommeil, faim ou n'en peut plus ?", "sous_titre": "Connaître ces signes, c'est le premier pas pour adapter son geste. Il n'y a pas de bonne réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (5,'essayer',$kk${"label": "À essayer pendant l'analyse", "titre": "Trois questions avant d'agir", "etapes": [{"titre": "Qu'est-ce que je vois ?", "texte": "Les faits, sans interpréter : ce que fait l'enfant, ce que je fais."}, {"titre": "Qu'est-ce que l'enfant me dit ?", "texte": "Fatigue, faim, satiété, besoin de finir son jeu, besoin d'être rassuré."}, {"titre": "Qu'est-ce que je change ?", "texte": "Le moment, le rythme, ou la façon de lui parler."}], "note": "On analyse la pratique, jamais la personne."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 3 % 2/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 14.2b

-- ---------------------------------------------------------------------------
-- 14.3a Trame de la séquence 3/3 (Test d'une pratique et retour d'expérience). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$L'autonomie, c'est pouvoir choisir entre faire seul ou être aidé, dans un cadre que l'adulte pose.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire ce qu'a changé la pratique testée pour l'enfant, et l'équipe a choisi une pratique commune qui laisse à l'enfant des choix dans un cadre donné.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Besoins physiologiques de l'enfant (soins, alimentation, sommeil)"}, "duree_min": 45, "materiel": ["Fiche de trace", "Engagements de la séance 2", "Paperboard"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Chacun relit son engagement de la séance 2 (« Cette semaine, je… »).", "Rappeler la règle : on raconte ce qu'on a fait, on ne se juge pas."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "L'autonomie, c'est pouvoir choisir entre faire seul ou être aidé, dans un cadre que l'adulte pose.", "idees": ["Plus les enfants sont actifs et ont des choix possibles dans un cadre donné, plus les tensions diminuent. Les soins, les repas et le coucher deviennent des moments de plaisir partagé, pas des moments redoutés.", "Quelques choix simples : choisir sa couche dans la pile à sa taille, finir son jeu avant le soin, faire seul ou être aidé au repas, garder ou non son pantalon pour la sieste, se débarbouiller et déposer sa serviette dans la panière.", "Patience et constance : mêmes horaires et mêmes rituels de coucher, on laisse à l'enfant le temps de s'endormir, et on lui fait confiance, comme on se fait confiance."], "support": "Projet pédagogique Koalakids, « Comment accompagner les enfants aux soins d'hygiène, au repas, au sommeil ? »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site (retour d'expérience)", "consigne": "Chacun raconte en une minute la pratique qu'il a testée. On cherche ce qui s'est passé, pas qui a bien ou mal fait.", "questions": ["Qu'ai-je testé, et dans quelle situation ?", "Qu'a fait l'enfant ? Qu'est-ce qui a changé, même un peu ?", "Qu'est-ce qui a été difficile ?", "Que gardons-nous en équipe ? Que changeons-nous ?"]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Choisir ensemble une pratique commune à tenir pendant deux semaines, puis un engagement par personne.", "amorce": "Cette semaine, je…", "consignes": ["Pratique commune : une phrase que chacun peut décrire de la même façon.", "Chacun s'engage sur un geste précis, noté sur la fiche de trace."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Tour de table : ce que je retiens du module 3. Annoncer le prochain module du programme et la date de la première séance."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 3 % 3/3 %';
-- FIN 14.3a

-- ---------------------------------------------------------------------------
-- 14.3b Blocs de la séquence 3/3. Attendu : 4 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Choisir, un peu, tous les jours", "paragraphes": ["L'autonomie de l'enfant ne consiste pas à tout faire seul. Elle consiste à **choisir** : faire seul ou être aidé, finir son jeu ou aller tout de suite, garder ou enlever son pantalon.", "Cette dernière séance sert à regarder ensemble ce que vous avez testé, et à choisir **une pratique commune** qui laisse de la place aux choix de l'enfant."]}$kk$),
  (1,'retenir',$kk${"titre": "À retenir", "points": ["**Des choix dans un cadre donné :** l'adulte pose le cadre, l'enfant choisit à l'intérieur.", "**Les tensions diminuent** quand l'enfant est acteur de ses soins, de son repas et de son coucher.", "**Patience et constance :** mêmes repères, même confiance, même rythme d'un jour à l'autre."]}$kk$),
  (2,'reflexion',$kk${"question": "Quel choix pourriez-vous proposer demain à un enfant, dans un moment où vous décidez tout aujourd'hui ?", "sous_titre": "Un petit choix suffit. Il n'y a pas de bonne réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (3,'essayer',$kk${"label": "À essayer après la séance", "titre": "Une pratique commune", "etapes": [{"titre": "La choisir ensemble.", "texte": "Un choix simple, que chacun propose de la même façon."}, {"titre": "La tenir deux semaines.", "texte": "Sans chercher la perfection : on note ce qui marche et ce qui coince."}, {"titre": "En reparler en équipe.", "texte": "À la prochaine réunion, quelques minutes pour dire ce qu'on garde."}], "note": "Toute pratique commune se décrit en une phrase."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 3 % 3/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 14.3b

-- ---------------------------------------------------------------------------
-- 14c Contrôle (lecture seule). Attendu : 3 séquences, blocs 5 / 6 / 4, publie = false.
-- ---------------------------------------------------------------------------
select m.titre, m.publie, (m.trame->>'objectif') is not null as objectif_ok,
       (select count(*) from public.bloc b where b.module_id = m.id) as blocs
from public.module m where m.titre like 'Module 3 %/3 %' order by m.ordre;
-- FIN 14c
